<?php
// Dedicated lab only. Concurrency exercises the actual PostgreSQL locks, separate PHP processes.
require getcwd().'/vendor/autoload.php';$app=require getcwd().'/bootstrap/app.php';$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
use App\Models\{Tenant,User,Conversation,ConversationMessage,Diagnostic};use App\Conversation\{Engine,Identity};use App\Tenancy\TenantContext;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
if(DB::connection()->getDatabaseName()!=='agent_center_lab')throw new RuntimeException('Lab required');
$ctx=app(TenantContext::class);try{$ctx->apply(platform:true);$tenant=Tenant::where('slug','recovery6-lab')->sole();$ctx->apply(tenantId:$tenant->id);$u=User::withoutGlobalScopes()->where('tenant_id',$tenant->id)->sole();$ctx->forUser($u);$identity=Identity::web($u);
if(($argv[1]??'parent')==='child'){$deadline=microtime(true)+15;while(!is_file($argv[4])){if(microtime(true)>$deadline)exit(3);usleep(1000);}$c=Conversation::findOrFail($argv[2]);$out=app(Engine::class)->send($identity,$c,$argv[3],$argv[5]);echo json_encode(['conversation'=>$out->id]);exit;}
function parallel($c,$same,$body){$dir=sys_get_temp_dir().'/conv-race-'.bin2hex(random_bytes(8));mkdir($dir,0700);$barrier=$dir.'/go';$key=(string)Str::uuid();$ps=[];for($i=0;$i<2;$i++){$p=proc_open([PHP_BINARY,__FILE__,'child',$c->id,$same?$key:(string)Str::uuid(),$barrier,$body],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);fclose($pipes[0]);$ps[]=[$p,$pipes];}touch($barrier);foreach($ps as [$p,$pipes]){$out=stream_get_contents($pipes[1]);stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);if(proc_close($p)!==0)throw new RuntimeException('Concurrent child failed; no payload emitted');if(!json_decode($out,true))throw new RuntimeException('Bad child response');}unlink($barrier);rmdir($dir);}
$c=app(Engine::class)->create($identity,(string)Str::uuid());parallel($c,true,'Testa DNS localhost');if(Diagnostic::where('id',$c->fresh()->current_diagnostic_id)->count()!==1||ConversationMessage::where('conversation_id',$c->id)->where('sender_type','user')->count()!==1)throw new RuntimeException('Duplicate execution');parallel($c,false,'Cancela');$c=$c->fresh();if($c->state!=='CANCELLED')throw new RuntimeException('Cancel state');$seq=ConversationMessage::where('conversation_id',$c->id)->orderBy('sequence')->pluck('sequence')->all();if($seq!==range(1,count($seq)))throw new RuntimeException('Sequence race');echo json_encode(['parallel_duplicate_message'=>'PASS','parallel_cancel'=>'PASS','ordered_history'=>'PASS']);
}finally{$ctx->apply();}
